const out = [];
for (const item of items) {
  const message = item.json?.message;
  const text = message?.data?.content;
  if (message?.isSelf) continue;
  if (typeof text !== 'string' || !text.trim()) continue;

  out.push({
    json: {
      threadId: message.threadId ?? '',
      threadType: message.type ?? '',
      groupName: message.data?.dName ?? '',
      senderId: message.data?.uidFrom ?? '',
      senderName: message.data?.dName ?? '',
      messageText: text.trim(),
      messageTs: message.data?.ts ?? '',
      messageId: message.data?.msgId ?? '',
      rawMessage: message,
    },
  });
}
return out;

const out = [];
for (const item of items) {
  const parts = item.json?.content?.parts ?? [];
  const textPart = parts.find((part) => typeof part?.text === 'string')?.text ?? '';
  const clean = textPart
    .replace(/^```json\s*/i, '')
    .replace(/^```/i, '')
    .replace(/```$/i, '')
    .trim();

  let data;
  try {
    data = JSON.parse(clean);
  } catch (error) {
    throw new Error(`Gemini did not return valid JSON: ${clean}`);
  }

  const tsNumber = Number(data.message_ts || Date.now());
  const receivedAt = Number.isFinite(tsNumber)
    ? new Date(tsNumber).toISOString()
    : new Date().toISOString();

  out.push({
    json: {
      received_at: receivedAt,
      thread_id: data.thread_id ?? '',
      group_name: data.group_name ?? '',
      sender_id: data.sender_id ?? '',
      sender_name: data.sender_name ?? '',
      message_text: data.message_text ?? '',
      message_ts: data.message_ts ?? '',
      summary: data.summary ?? '',
      category: data.category ?? 'other',
      intent: data.intent ?? '',
      action_required: data.action_required ?? false,
      action_type: data.action_type ?? 'other',
      customer_name: data.customer_name ?? '',
      phone: data.phone ?? '',
      address: data.address ?? '',
      product: data.product ?? '',
      quantity: Number(data.quantity ?? 0),
      unit: data.unit ?? '',
      amount: Number(data.amount ?? 0),
      due_date: data.due_date ?? '',
      priority: data.priority ?? 'medium',
      confidence: Number(data.confidence ?? 0),
      raw_ai_json: clean,
    },
  });
}
return out;
